# FDN Pilfer {1}{B} Sorcery
# "Target opponent reveals their hand. You choose a nonland card from it. That player discards that card."
# Shape: M21 Duress (verified), with the filter "nonland" alone (one-part filter written bare).
# The designation is TARGET_OPPONENT on the reveal (the B5b-reveal-hand template's own bytes);
# the later steps read the same binding through TARGET_PLAYER, as Duress's templates write them.
abilities = [
    SpellAbility(
        kind=SpellKind.SORCERY,
        effect=Seq(
            steps=(
                A(Verb.REVEAL, {'controller': ControllerRef.TARGET_OPPONENT, 'count': QUnbounded()}),
                A(Verb.CHOOSE, {
                    'count': QConst(value=1),
                    'target': Selector(
                        count=QUnbounded(),
                        mode=SelectorMode.ALL,
                        filter=FNot(inner=FAtom(pred=FAtomPred.TYPE_EQ, string_value='Land')),
                        zones=(Zone(kind=ZoneKind.HAND, controller=ControllerRef.TARGET_PLAYER),),
                    ),
                }),
                A(Verb.MOVE_ZONE, {
                    'cards': Selector(
                        count=QConst(value=1),
                        mode=SelectorMode.CHOOSE,
                        filter=FAnd(children=()),
                        zones=(Zone(kind=ZoneKind.ANY, controller=ControllerRef.ANY),),
                        referent='result',
                    ),
                    'controller': ControllerRef.TARGET_PLAYER,
                    'destination': Zone(kind=ZoneKind.GRAVEYARD, controller=ControllerRef.TARGET_PLAYER),
                    'from': Zone(kind=ZoneKind.HAND, controller=ControllerRef.TARGET_PLAYER),
                }),
            ),
        ),
    ),
]
